{"files":[{"path":"src/occupationalInfo/date.mjs","content":"function isValidCalendarDate(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (month < 1 || month > 12) return false;
  if (day < 1) return false;
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day <= daysInMonth[month - 1];
}

export function validateSurveyDate(value, today) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return '日期格式错误';
  if (!isValidCalendarDate(value)) return '日期无效';
  if (typeof today !== 'string' || !isValidCalendarDate(today)) return '日期无效';
  if (value > today) return '调查日期不能晚于今日';
  return '';
}
